mapper.select:
SELECT 
    ,
    d.dept_name as department_name,
    p.dict_value as professionName,
    r.inspector as inspector_name,
    r.responsible_person as responsible_person_name,
    u5.real_name as reviewer_name

FROM sys_inspection_record r
LEFT JOIN sys_dept d ON r.department_id = d.id AND d.deleted = 0
LEFT JOIN sys_dictionary p ON r.profession_id = p.id AND p.deleted = 0
LEFT JOIN sys_user u5 ON r.reviewer_id = u5.id AND u5.deleted = 0

WHERE r.deleted = 0

    AND r.department_id = #{departmentId}


    AND r.profession_id = #{professionId}


    AND EXISTS (
        SELECT 1 FROM sys_dictionary nd 
        WHERE nd.id = #{natureId} 
        AND nd.dict_value = r.nature_definition 
        AND nd.deleted = 0
    )


    AND r.location LIKE CONCAT('%', #{locationId}, '%')


    AND r.inspector = #{inspectorId}


    AND r.responsible_unit = #{responsibleUnitId}


    AND r.responsible_person = #{responsiblePersonId}


    AND r.reviewer_id = #{reviewerId}


    AND r.problem_description LIKE CONCAT('%', #{problemDescription}, '%')


    AND r.responsible_person LIKE CONCAT('%', #{responsiblePerson}, '%')





            AND r.status IN

                #{item}



            AND r.status = #{status}




    AND r.create_time >= #{startTime}


    AND r.create_time <= #{endTime}

ORDER BY p.sort_order ASC, r.create_time DESC

SELECT d.dept_name AS department_name, p.dict_value AS profession_name, COUNT(r.id) AS count FROM sys_inspection_record r LEFT JOIN sys_dept d ON r.department_id = d.id AND d.deleted = 0 -- 关联有效部门 LEFT JOIN sys_dictionary p ON r.profession_id = p.id AND p.deleted = 0 -- 关联有效职业 WHERE r.deleted = 0 -- 主表有效记录 AND d.id IS NOT NULL -- 过滤部门为空（未匹配到部门）的数据
AND r.department_id = #{departmentId}
AND r.status = #{status}
AND DATE(r.create_time) >= #{startDate}
AND DATE(r.create_time) <= #{endDate}
GROUP BY d.id, d.dept_name, p.id, p.dict_label ORDER BY d.dept_name ASC, p.dict_value ASC

SELECT d.dept_name AS department_name, COALESCE(r.nature_definition, '未定义') AS nature_name, COUNT(r.id) AS count FROM sys_inspection_record r LEFT JOIN sys_dept d ON r.department_id = d.id AND d.deleted = 0 WHERE r.deleted = 0 AND d.id IS NOT NULL
AND r.department_id = #{departmentId}
AND r.status = #{status}
AND DATE(r.create_time) >= #{startDate}
AND DATE(r.create_time) <= #{endDate}
GROUP BY d.id, d.dept_name, r.nature_definition ORDER BY d.dept_name ASC, nature_name ASC

SELECT FROM sys_inspection_record r WHERE r.responsible_person = #{userId} AND r.deleted = 0
AND r.status = #{status}
ORDER BY r.create_time DESC

SELECT status, CASE WHEN status = 0 THEN '待整改' WHEN status = 1 THEN '整改中' WHEN status = 2 THEN '待复查' WHEN status = 3 THEN '已完成' WHEN status = 4 THEN '已提交' ELSE '未知状态' END as status_name, COUNT(1) as count FROM sys_inspection_record WHERE deleted = 0
AND department_id = #{departmentId}
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY status

SELECT p.dict_value as profession_name, COUNT(r.id) as count FROM sys_dictionary p LEFT JOIN sys_inspection_record r ON p.id = r.profession_id AND r.deleted = 0 WHERE p.deleted = 0 AND p.dict_type = 'profession'
AND r.department_id = #{departmentId}
AND DATE(r.create_time) >= #{startDate}
AND DATE(r.create_time) <= #{endDate}
GROUP BY p.id, p.dict_value HAVING count > 0 ORDER BY count DESC

SELECT r.location as location_name, COUNT(r.id) as count FROM sys_inspection_record r WHERE r.deleted = 0 AND r.location IS NOT NULL AND r.location != ''
AND r.department_id = #{departmentId}
AND DATE(r.create_time) >= #{startDate}
AND DATE(r.create_time) <= #{endDate}
GROUP BY r.location HAVING count > 0 ORDER BY count DESC

SELECT r.responsible_person as responsible_person_name, COUNT(r.id) as count FROM sys_inspection_record r WHERE r.deleted = 0 AND r.responsible_person IS NOT NULL AND r.responsible_person != ''
AND r.department_id = #{departmentId}
AND DATE(r.create_time) >= #{startDate}
AND DATE(r.create_time) <= #{endDate}
GROUP BY r.responsible_person HAVING count > 0 ORDER BY count DESC

SELECT CASE WHEN status = 0 THEN '待整改' WHEN status = 1 THEN '待复查' WHEN status = 2 THEN '已完成' ELSE '未知状态' END as status_name, COUNT(1) as count FROM sys_inspection_record WHERE deleted = 0
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY status

SELECT p.dict_value as profession_name, COUNT(r.id) as count FROM sys_dictionary p LEFT JOIN sys_inspection_record r ON p.id = r.profession_id AND r.deleted = 0 WHERE p.deleted = 0 AND p.dict_type = 'profession'
AND r.department_id = #{departmentId}
AND DATE(r.create_time) >= #{startDate}
AND DATE(r.create_time) <= #{endDate}
GROUP BY p.id, p.dict_value HAVING count > 0 ORDER BY count DESC

SELECT r.location as location_name, COUNT(r.id) as count FROM sys_inspection_record r WHERE r.deleted = 0 AND r.location IS NOT NULL AND r.location != ''
AND r.department_id = #{departmentId}
AND DATE(r.create_time) >= #{startDate}
AND DATE(r.create_time) <= #{endDate}
GROUP BY r.location HAVING count > 0 ORDER BY count DESC

SELECT r.responsible_person as responsible_person_name, COUNT(r.id) as count FROM sys_inspection_record r WHERE r.deleted = 0 AND r.responsible_person IS NOT NULL AND r.responsible_person != ''
AND r.department_id = #{departmentId}
AND DATE(r.create_time) >= #{startDate}
AND DATE(r.create_time) <= #{endDate}
GROUP BY r.responsible_person HAVING count > 0 ORDER BY count DESC

SELECT COUNT(*)
FROM sys_inspection_record r
WHERE r.deleted = 0

    AND r.department_id = #{departmentId}


    AND r.inspector = #{userId}


    AND r.status = #{status}


    AND r.create_time >= #{weekStart}


    AND r.create_time <= #{weekEnd}

SELECT , r.group_leader_name as group_leader_name, r.deputy_leader_name as deputy_leader_name, d.dept_name as department_name, p.dict_value as professionName, r.inspector as inspector_name, r.responsible_person as responsible_person_name, u5.real_name as reviewer_name FROM sys_inspection_record r LEFT JOIN sys_dept d ON r.department_id = d.id AND d.deleted = 0 LEFT JOIN sys_dictionary p ON r.profession_id = p.id AND p.deleted = 0 LEFT JOIN sys_user u5 ON r.reviewer_id = u5.id AND u5.deleted = 0 WHERE r.deleted = 0 AND r.status = 0 AND r.rectification_deadline <= #{currentTime}
AND r.department_id = #{departmentId}
ORDER BY r.rectification_deadline ASC

SELECT COUNT(*)
FROM sys_inspection_record
WHERE deleted = 0

    AND department_id = #{departmentId}


    AND status = #{status}

SELECT COUNT(*) FROM sys_inspection_record WHERE deleted = 0
AND department_id = #{departmentId}
AND YEAR(create_time) = YEAR(CURDATE()) AND MONTH(create_time) = MONTH(CURDATE())

SELECT COUNT(*) FROM sys_inspection_record WHERE deleted = 0
AND department_id = #{departmentId}
AND YEAR(create_time) = YEAR(DATE_SUB(CURDATE(), INTERVAL 1 MONTH)) AND MONTH(create_time) = MONTH(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))

SELECT DATE_FORMAT(create_time, '%Y-%m') as month, COUNT(*) as count FROM sys_inspection_record WHERE deleted = 0
AND department_id = #{departmentId}
AND create_time >= DATE_SUB(CURDATE(), INTERVAL 12 MONTH) GROUP BY DATE_FORMAT(create_time, '%Y-%m') ORDER BY month ASC

SELECT , r.group_leader_name as group_leader_name, r.deputy_leader_name as deputy_leader_name, d.dept_name as department_name, p.dict_value as professionName, r.inspector as inspector_name, r.responsible_person as responsible_person_name, u5.real_name as reviewer_name FROM sys_inspection_record r LEFT JOIN sys_dept d ON r.department_id = d.id AND d.deleted = 0 LEFT JOIN sys_dictionary p ON r.profession_id = p.id AND p.deleted = 0 LEFT JOIN sys_user u5 ON r.reviewer_id = u5.id AND u5.deleted = 0 WHERE r.deleted = 0
AND r.status = #{status}
AND r.profession_id = #{professionId}
AND r.location LIKE CONCAT('%', #{locationId}, '%')
AND r.inspector LIKE CONCAT('%', #{checkerName}, '%')
AND r.responsible_person LIKE CONCAT('%', #{responsiblePerson}, '%')
AND r.create_time >= #{startTime}
AND r.create_time <= #{endTime}
AND r.department_id = #{departmentId}
AND EXISTS ( SELECT 1 FROM sys_dictionary nd WHERE nd.id = #{natureId} AND nd.dict_value = r.nature_definition AND nd.deleted = 0 )
AND r.problem_description LIKE CONCAT('%', #{problemDescription}, '%')
ORDER BY p.sort_order ASC, r.create_time DESC
